def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def get_pos(key, default=None):
        v = observation.get(key, default)
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    def step_toward(src, dst):
        if src is None or dst is None:
            return [0, 0]
        sx, sy = src
        tx, ty = dst
        return [clamp_step(tx - sx), clamp_step(ty - sy)]

    def dist2(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def best_of(points, src, prefer_far=False):
        if not points:
            return None
