            score = -d if prefer_far else d
            if best is None or score < best_score or (score == best_score and (p[0], p[1]) < (best[0], best[1])):
                best = (p[0], p[1])
                best_score = score
        return best

    env = observation.get("environment_name", "resource_collection")
    self_pos = get_pos("self_position", (0, 0))
    opp_pos = get_pos("opponent_position", None)
    grid_w = observation.get("grid_width", 0) or 0
    grid_h = observation.get("grid_height", 0) or 0
    center = (grid_w // 2, grid_h // 2) if grid_w and grid_h else None

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            if opp_pos is not None:
                return step_toward(self_pos, opp_pos)
            return [0, 0]
        # evader: move away from pursuer/opponent, else toward a corner farthest from center
        if opp_pos is not None:
            dx = clamp_step(self_pos[0] - opp_pos[0])
            dy = clamp_step(self_pos[1] - opp_pos[1])
            if dx == 0 and dy == 0:
