        if opp_pos is not None:
            if center is not None:
                # prefer between opponent and center to avoid over-committing
                if dist2(self_pos, opp_pos) > dist2(self_pos, center):
                    return step_toward(self_pos, center)
            return step_toward(self_pos, opp_pos)
        if center is not None:
            return step_toward(self_pos, center)
        return [0, 0]

    # resource_collection and fallback
    resources = observation.get("resources") or observation.get("resource_cells") or observation.get("food") or []
